// Audio.sink?.audio.volume ?? 0: 0 without a sink; a volume is a number, never null
qs::PwNode* node = ::ii::services::Audio::instance().sink.get();
if (node == nullptr) {
  return 0.0;
}
qs::PwNodeAudio* audio = node->audio.get();
if (audio == nullptr) {
  // ?. guards only sink: reading .volume of a null audio is a TypeError, and the binding keeps its value
  throw std::runtime_error("TypeError: Cannot read property 'volume' of null");
}
return static_cast<double>(audio->volume.get());

