// Audio.sink?.audio.muted: undefined (falsy) without a sink
qs::PwNode* node = ::ii::services::Audio::instance().sink.get();
if (node == nullptr) {
  return std::string("volume_up");
}
qs::PwNodeAudio* audio = node->audio.get();
if (audio == nullptr) {
  // ?. guards only sink: reading .muted of a null audio is a TypeError, and the binding keeps its value
  throw std::runtime_error("TypeError: Cannot read property 'muted' of null");
}
return audio->muted.get() ? std::string("volume_off") : std::string("volume_up");
